import{_ as l,l as o,o as e,c as h,v as r,p as i,x as n,d,i as s,S as _}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"Garman–Kohlhagen","description":"","frontmatter":{"title":"Garman–Kohlhagen","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/garman-kohlhagen.md","filePath":"quant/garman-kohlhagen.md","lastUpdated":1789023840000}'),p={name:"quant/garman-kohlhagen.md"};function m(c,a,u,f,B,g){const t=o("Mermaid");return e(),h("div",null,[a[1]||(a[1]=r('<h1 id="garman–kohlhagen" tabindex="-1">Garman–Kohlhagen <a class="header-anchor" href="#garman–kohlhagen" aria-label="Permalink to &quot;Garman–Kohlhagen&quot;">​</a></h1><div class="epigraph"><p>外汇期权是支付外国货币利率「股息」的股权期权；国内利率是融资，国外利率是持有外币的收益。</p><footer>—— Garman and Kohlhagen, Foreign Currency Option Values, Journal of International Money and Finance, 1983</footer></div><p><a href="/quant/xva-bridge">上一课</a>结束希腊与模型风险课序。本课打开「股权之外」：FX 的 Black–Scholes 叫 Garman–Kohlhagen（GK）。缺口不是再推 <a href="/quant/bsm">BSM</a>，而是把 \\(q\\) 换成外国利率 \\(r_f\\)，并把即期、远期、Dom/For 惯例对齐。后课 ATM/RR/BF 在 GK 坐标上报价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>即期 \\(S\\) 是一单位外币的本币价格。持有外币赚 \\(r_f\\)，融资本币付 \\(r_d\\)。GK 看涨是 \\(e^{-r_d T}S\\) 项里用 \\(r_f\\) 做「股息」：\\(Se^{-r_f T}N(d_1)-Ke^{-r_d T}N(d_2)\\)。这与带连续股息的 BSM 同构。问题是市场交易的是<strong>远期</strong>与 pips，不是这个现货公式的字面输入：Black 公式用 \\(F=S e^{(r_d-r_f)T}\\)，波动是远期隐波。把股权股息曲线直接当 \\(r_f\\)，会漏掉 FX swap 点与基差。</p><p>第二问题是哪一侧是 call：USD call JPY put 与报价方向、\\(K\\) 的单位绑在一起。惯例课已经警告；GK 实现必须先固定 \\(S\\) 的定义。</p><h3 id="利率平价先于期权" tabindex="-1">利率平价先于期权 <a class="header-anchor" href="#利率平价先于期权" aria-label="Permalink to &quot;利率平价先于期权&quot;">​</a></h3><p>无套利远期由 FX swap 给出，不一定等于教科书 \\(S e^{(r_d-r_f)T}\\)（交叉货币基差）。定价应取市场远期，把 \\(r_d-r_f\\) 当隐含，而不是从两个 SOFR/TONA 曲线硬算 \\(F\\) 再标期权。基差对象在 <a href="/quant/xccy-basis">交叉货币基差</a> 与后课交叉货币互换。</p><p><span class="marginnote">GK 仍是对数正态、常数 vol。微笑、触碰、障碍全部超出本公式；本课只钉无微笑的坐标系。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输入：市场即期、市场远期或 FX swap、本外币贴现、到期日计数、是否 premium-adjusted。用 Black-76 对远期定价，输出 GK 希腊值时注意 Delta 是现货 Delta 还是远期 Delta。对冲：现货或远期 FX 对冲 Delta，利率台对冲 \\(r_d,r_f\\) 的 Rho——FX 期权的 Rho 是两个方向。不要用股权指数期货去对冲 quanto 已在 quanto 课写过；普通 FX 期权对冲的是 \\(S\\) 本身。</p><p>数字与障碍在 FX 里极常见，GK 闭式可当基准，生产用带微笑的模型。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>外币像连续支付 \\(r_f\\) 的「股票」，本币是计价。Ito 与贴现后，风险中性漂移是 \\(r_d-r_f\\)。这就是利率平价在扩散里的样子。波动是 \\(S\\) 的对数波动，不是「外币资产」另一次。GK 与 BSM 的同构让股权代码可复用，但市场数据适配器不能复用股权的股息估计算法。</p>',14)),(e(),i(_,null,{default:n(()=>[s(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Spot%5B%22%E5%8D%B3%E6%9C%9F%20S%22%5D%20--%3E%20F%5B%22%E5%B8%82%E5%9C%BA%E8%BF%9C%E6%9C%9F%20FX%20swap%22%5D%0A%20%20Rd%5B%22%E6%9C%AC%E5%B8%81%E5%88%A9%E7%8E%87%22%5D%20--%3E%20F%0A%20%20Rf%5B%22%E5%A4%96%E5%B8%81%E5%88%A9%E7%8E%87%22%5D%20--%3E%20F%0A%20%20F%20--%3E%20Blk%5B%22Black-76%22%5D%0A%20%20Blk%20--%3E%20GK%5B%22GK%20%E4%BB%B7%E6%A0%BC%E4%B8%8E%E5%8F%8C%20Rho%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>微笑使每个 Delta 一个 vol，GK 只解释 ATM 水平。负利率下外汇仍可用 lognormal（即期为正），与后课利率移位不同。NDF 货币没有可交割远期，用 NDF 定盘，见 <a href="/quant/ndf">NDF</a>。周末日历与 Tokyo fixing 等使 \\(T\\) 不是日历差除以 365。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GK 是带外国利率当股息的 BSM；生产用市场远期进 Black-76。</li><li>Delta 惯例与 call/put 方向必须先固定。</li><li>双 Rho；基差使教科书利率平价不等于市场 \\(F\\)。</li><li>出处：Garman and Kohlhagen, <em>JIMF</em>, 1983。</li></ul>',4))])}const S=l(p,[["render",m]]);export{F as __pageData,S as default};
